// This function filters and formats alert-worthy personnel
const highDifficultyThreshold = 11; 

const rows = items;
const alerts = [];

for (const row of rows) {
  const name = row.json['Name'];
  const difficulty = parseFloat(row.json['Difficulty to Clear Leave']);

  if (difficulty >= highDifficultyThreshold) {
    alerts.push(`• ${name} – Difficulty to Clear Leave: ${difficulty.toFixed(2)}`);
  }
}

return [{
  json: {
    alertText: alerts.length > 0 
      ? `📢 *Leave Alert Summary (Every Shift)*\n\nThe following personnel need attention:\n\n${alerts.join('\n')}`
      : '✅ All personnel are within leave thresholds this week.'
  }
}];
